SELECT CASE WHEN duration_sec >= 463 THEN 'high' WHEN duration_sec >= 85 THEN 'mid' ELSE 'low' END AS duration_sec_bucket, HOUR(event_time) AS event_hour, MIN(event_time) AS first_event_time, ROUND(AVG(duration_sec), 2) AS avg_duration_sec, ROUND(STDDEV(duration_sec), 2) AS stddev_duration_sec FROM web_events WHERE page = '/home' AND event_type IN ('purchase', 'page_view') GROUP BY 1, 2 ORDER BY event_hour, duration_sec_bucket
